import { test, expect } from '@playwright/test';

test.describe('Dropdown Functionality Tests', () => {
  test('should display the disabled prompt initially', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await expect(page.locator('#dropdown')).toBeVisible();
    await expect(page.locator('#dropdown')).toHaveAttribute('value', '');
  });

  test('should select the option with text "Option 2"', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', 'Option 2');
    await expect(page.locator('#dropdown')).toBeVisible();
    await expect(page.locator('#dropdown')).toHaveAttribute('value', '2');
  });
});
